#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Shape : 4
COMPONENT Networking : 4
COMPONENT DIS : 2
COMPONENT Scripting : 1
COMPONENT KeyDeviceSensor : 1
COMPONENT EventUtilities : 1
COMPONENT Text : 2
COMPONENT X_ITE : 1

PROTO P [
  initializeOnly SFVec3f c 0 0 0
]
{
  Group {
    children ReceiverPdu {
      bboxDisplay TRUE
      bboxSize 0.8 0.8 0.8
      bboxCenter IS c
    }
  }
}

Viewpoint {
  position 0 0 12
}

Background {
  skyColor 0.15 0.15 0.18
}

DirectionalLight {
  intensity 0.9
  direction -0.4 -0.6 -0.7
}

Transform {
  translation -3 3 0
  children Switch {
    whichChoice 1
  }
}

Transform {
  translation 0 3 0
  children LOD {
    range 100
  }
}

Transform {
  translation 3 3 0
  children Billboard {
    axisOfRotation 0 0 0
    children SignalPdu {
      bboxDisplay TRUE
      bboxSize 1 1 0.2
    }
  }
}

Transform {
  translation -3 1 0
  children Anchor {
    url "x.wrl"
    children TransmitterPdu {
      bboxDisplay TRUE
      bboxSize 1 1 1
    }
  }
}

Transform {
  translation 0 1 0
  children Collision {
    children ReceiverPdu {
      bboxDisplay TRUE
      bboxSize 1 1 1
    }
  }
}

Transform {
  translation 3 1 0
  children StaticGroup {
    children [
      ReceiverPdu {
        bboxDisplay TRUE
        bboxSize 1 1 1
      }
      Shape {
        geometry Sphere {
          radius 0.3
        }
      }
    ]
  }
}

Transform {
  translation -3 -1 0
  children Inline {
    url "dis-bbox-inline.wrl"
  }
}

Transform {
  translation 0 -1 0
  children P {
    c 0 0.5 0
  }
}

Transform {
  translation 3 -1 0
  scale 0 1 1
  children ReceiverPdu {
    bboxDisplay TRUE
    bboxSize 1 1 1
  }
}

Transform {
  translation -3 -3 0
  children ReceiverPdu {
    bboxDisplay TRUE
    bboxSize -1 1 1
  }
}

Transform {
  translation 0 -3 0
  children SignalPdu {
    bboxDisplay TRUE
    bboxSize 0 0 0
  }
}

Transform {
  translation 3 -3 0
  children TransmitterPdu {
    bboxDisplay TRUE
    bboxSize 1 1 -2
    bboxCenter 0 0.5 0
  }
}

Transform {
  translation 0 -4.3 0
  rotation 1 0 0 0.5
  children TransmitterPdu {
    bboxDisplay TRUE
    bboxSize 1 0 1
  }
}

